import sqlite3
import subprocess

from agents import function_tool

_DATABASE_PATH = "/var/data/recruiting.db"
_PROVISIONING_SCRIPT_PATH = "/opt/hr/scripts/provision_new_hire.sh"
_ALLOWED_ROLES = {"engineer", "sales_rep", "recruiter", "analyst", "designer"}


@function_tool
def run_onboarding_provisioning_for_hire(candidate_id: int, access_role: str) -> str:
    if access_role not in _ALLOWED_ROLES:
        return "Role not allowed: " + access_role

    database_connection = sqlite3.connect(_DATABASE_PATH)
    try:
        candidate_row_from_database = database_connection.execute(
            "SELECT work_email, offer_status FROM candidates WHERE id = ?",
            (candidate_id,),
        ).fetchone()
        if candidate_row_from_database is None:
            return "Candidate not found"

        candidate_work_email_address, current_offer_status = candidate_row_from_database
        if current_offer_status != "accepted":
            return "Offer has not been accepted"

        provisioning_process_result = subprocess.run(
            [_PROVISIONING_SCRIPT_PATH, candidate_work_email_address, access_role],
            capture_output=True,
            text=True,
            timeout=120,
        )
        if provisioning_process_result.returncode != 0:
            return "Provisioning failed: " + provisioning_process_result.stderr.strip()

        database_connection.execute(
            "INSERT INTO role_grants (candidate_id, role_name) VALUES (?, ?)",
            (candidate_id, access_role),
        )
        database_connection.commit()
    finally:
        database_connection.close()

    return "Provisioned " + candidate_work_email_address + " with role " + access_role

import sqlite3

from langchain_core.tools import tool

_DATABASE_PATH = "/var/data/recruiting.db"


@tool
def search_applicants_by_skill(job_id: int, skill: str, min_years_experience: int = 0, limit: int = 20) -> dict:
    if job_id <= 0:
        return {"error": "job_id must be positive"}
    if not skill or not skill.strip():
        return {"error": "skill is required"}
    if min_years_experience < 0:
        return {"error": "min_years_experience cannot be negative"}
    if limit < 1 or limit > 100:
        return {"error": "limit must be between 1 and 100"}

    connection = sqlite3.connect(_DATABASE_PATH)
    connection.row_factory = sqlite3.Row
    try:
        job_row = connection.execute("SELECT id FROM jobs WHERE id = ?", (job_id,)).fetchone()
        if job_row is None:
            return {"error": "job not found"}

        rows = connection.execute(
            "SELECT a.id, a.full_name, a.years_experience, a.stage "
            "FROM applicants a JOIN applicant_skills s ON s.applicant_id = a.id "
            "WHERE a.job_id = ? AND LOWER(s.skill) = LOWER(?) AND a.years_experience >= ? "
            "ORDER BY a.years_experience DESC LIMIT ?",
            (job_id, skill.strip(), min_years_experience, limit),
        ).fetchall()
    finally:
        connection.close()

    return {"count": len(rows), "applicants": [dict(row) for row in rows]}

from dataclasses import dataclass

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("recruiting")


@dataclass
class ShareResult:
    candidate_id: int
    interviewer_id: int
    granted: bool


@mcp.tool()
def share_candidate_scorecard_with_interviewer(candidate_id: int, interviewer_id: int) -> ShareResult:
    import sqlite3
    connection = sqlite3.connect("/var/data/recruiting.db")
    with connection:
        connection.execute(
            "INSERT OR IGNORE INTO scorecard_access (candidate_id, interviewer_id, permission) VALUES (?, ?, 'edit')",
            (candidate_id, interviewer_id),
        )
    connection.close()
    return ShareResult(candidate_id, interviewer_id, True)
